'use client';

import React from 'react';
import { DemoActor } from '../lib/types';
import { SIMULATED_ACTORS } from '../lib/data';

interface ModeSwitchProps {
  actors: DemoActor[];
  selectedActor: string;
  onSelectActor: (actorId: string) => void;
  onConnect: () => void;
  isConnecting: boolean;
  isConnected: boolean;
  sessionRole: string | null;
}

export const ModeSwitch: React.FC<ModeSwitchProps> = ({
  actors,
  selectedActor,
  onSelectActor,
  onConnect,
  isConnecting,
  isConnected,
  sessionRole,
}) => {
  const activeActors = actors.length > 0 ? actors : SIMULATED_ACTORS;

  return (
    <div>
      <header className="app-header">
        <div className="brand-title">
          <span>🏦 Bankai Dispute Support</span>
          <span className="brand-badge" style={{ backgroundColor: 'var(--blue-soft)', color: 'var(--blue-primary)', padding: '0.25rem 0.6rem', borderRadius: '12px', fontSize: '0.75rem', fontWeight: 700 }}>
            🟢 BACKEND REAL EN VIVO
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem' }}>
          <div className="connection-inputs" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <label htmlFor="actor-select" style={{ fontSize: '0.82rem', fontWeight: 600, color: 'var(--text-ink)' }}>
              Usuario:
            </label>
            <select
              id="actor-select"
              className="select-actor"
              value={selectedActor}
              onChange={(e) => onSelectActor(e.target.value)}
              style={{ padding: '0.3rem 0.6rem', fontSize: '0.82rem', borderRadius: 'var(--control-radius)', border: '1px solid var(--line-color)' }}
            >
              {activeActors.map((actor) => (
                <option key={actor.actorId} value={actor.actorId}>
                  {actor.label} ({actor.role})
                </option>
              ))}
            </select>

            <button
              className="btn-primary"
              onClick={onConnect}
              disabled={isConnecting}
              type="button"
              style={{ padding: '0.3rem 0.75rem', fontSize: '0.8rem' }}
            >
              {isConnecting ? 'Conectando...' : isConnected ? 'Reconectar' : 'Conectar'}
            </button>
          </div>

          <div className={`status-badge ${isConnected ? 'connected' : 'disconnected'}`}>
            <span className={`status-dot ${isConnected ? 'connected' : 'disconnected'}`}></span>
            <span>{isConnected ? `Conectado (${sessionRole || 'OK'})` : 'Desconectado'}</span>
          </div>
        </div>
      </header>
    </div>
  );
};
