'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { ServerEvent, ConversationSnapshot } from './types';

const WS_URL = process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:3000/v1/realtime';

export interface UseRealtimeOptions {
  enabled: boolean;
  onEvent?: (event: ServerEvent) => void;
  onSnapshot?: (snapshot: ConversationSnapshot) => void;
  onDelta?: (delta: { threadId: string | null; value: string; messageId: string }) => void;
  onCompleted?: (completed: { threadId: string | null; response: string; status: string }) => void;
  onAlert?: (alert: { approvalId: string; threadId: string | null }) => void;
  onProblem?: (problem: { code: string; threadId: string | null }) => void;
  onStateChange?: (state: { status: string; threadId: string | null }) => void;
}

export function useRealtime(options: UseRealtimeOptions) {
  const [isConnected, setIsConnected] = useState(false);
  const [eventLogs, setEventLogs] = useState<ServerEvent[]>([]);
  const wsRef = useRef<WebSocket | null>(null);

  const addLog = useCallback((evt: ServerEvent) => {
    let isWarning = false;
    if (evt.type === 'problem') {
      isWarning = true;
    } else if (evt.type === 'session.ready' && (!evt.payload?.userId || !Array.isArray(evt.payload?.roles))) {
      isWarning = true;
    } else if (evt.type === 'conversation.snapshot' && (!evt.payload?.threadId || !evt.payload?.trace)) {
      isWarning = true;
    }

    const logItem: ServerEvent = {
      ...evt,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      isWarning,
    };

    setEventLogs((prev) => [logItem, ...prev]);
  }, []);

  const connect = useCallback(() => {
    if (!options.enabled) return;
    if (wsRef.current && (wsRef.current.readyState === WebSocket.OPEN || wsRef.current.readyState === WebSocket.CONNECTING)) {
      return;
    }

    try {
      const ws = new WebSocket(WS_URL);
      wsRef.current = ws;

      ws.onopen = () => {
        setIsConnected(true);
      };

      ws.onmessage = (event) => {
        try {
          const parsed: ServerEvent = JSON.parse(event.data);
          addLog(parsed);

          if (options.onEvent) options.onEvent(parsed);

          switch (parsed.type) {
            case 'conversation.snapshot':
              if (options.onSnapshot && parsed.payload) {
                options.onSnapshot(parsed.payload);
              }
              break;
            case 'run.state':
              if (options.onStateChange && parsed.payload?.status) {
                options.onStateChange({ status: parsed.payload.status, threadId: parsed.threadId });
              }
              break;
            case 'assistant.delta':
              if (options.onDelta && parsed.payload?.value) {
                options.onDelta({
                  threadId: parsed.threadId,
                  value: parsed.payload.value,
                  messageId: parsed.payload.messageId,
                });
              }
              break;
            case 'assistant.completed':
              if (options.onCompleted && parsed.payload?.response) {
                options.onCompleted({
                  threadId: parsed.threadId,
                  response: parsed.payload.response,
                  status: parsed.payload.status,
                });
              }
              break;
            case 'backoffice.alert':
              if (options.onAlert && parsed.payload?.approvalId) {
                options.onAlert({
                  approvalId: parsed.payload.approvalId,
                  threadId: parsed.threadId,
                });
              }
              break;
            case 'problem':
              if (options.onProblem && parsed.payload?.code) {
                options.onProblem({
                  code: parsed.payload.code,
                  threadId: parsed.threadId,
                });
              }
              break;
          }
        } catch (e) {
          console.error('Error parsing WS message:', e);
        }
      };

      ws.onclose = () => {
        setIsConnected(false);
      };

      ws.onerror = (err) => {
        setIsConnected(false);
      };
    } catch (e) {
      console.warn('WS connection attempt pending session cookie initialization');
    }
  }, [options, addLog]);

  const disconnect = useCallback(() => {
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    setIsConnected(false);
  }, []);

  const sendChat = useCallback((data: { clientMessageId: string; text?: string; threadId?: string; attachmentIds?: string[] }) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      console.warn('Cannot send WS message: Socket not open');
      return false;
    }

    const payload = {
      type: 'chat.send',
      clientMessageId: data.clientMessageId,
      ...(data.threadId ? { threadId: data.threadId } : {}),
      ...(data.text ? { text: data.text } : {}),
      attachmentIds: data.attachmentIds || [],
    };

    wsRef.current.send(JSON.stringify(payload));
    addLog({
      type: 'chat.send' as any,
      threadId: data.threadId || null,
      traceId: null,
      revision: null,
      payload,
    });
    return true;
  }, [addLog]);

  const subscribeThread = useCallback((threadId: string) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) return;
    const payload = {
      type: 'conversation.subscribe',
      threadId,
    };
    wsRef.current.send(JSON.stringify(payload));
    addLog({
      type: 'conversation.subscribe' as any,
      threadId,
      traceId: null,
      revision: null,
      payload,
    });
  }, [addLog]);

  const clearLogs = useCallback(() => {
    setEventLogs([]);
  }, []);

  useEffect(() => {
    if (!options.enabled) {
      disconnect();
    }
    return () => {
      disconnect();
    };
  }, [options.enabled, disconnect]);

  return {
    isConnected,
    eventLogs,
    connect,
    disconnect,
    sendChat,
    subscribeThread,
    clearLogs,
  };
}
